def bridge(scenario):
    # The schema guarantees both keys; the fallbacks only keep a malformed
    # fixture from turning into an uncaught exception.
    routes = scenario.get("routes") or {}
    events = scenario.get("events") or ()

    # Every distinct origin label gets a pipeline, used or not.
    pipelines = {}
    for label in routes.values():
        if label not in pipelines:
            pipelines[label] = bytearray()

    # Buffer each observed stream, including one first seen in a terminal,
    # DATA or unknown frame.  Unknown frames contribute nothing anywhere.
    streams = {}
    for index, event in enumerate(events):
        sid = event["sid"]
        kind = event["type"]
        state = streams.get(sid)
        if state is None:
            state = streams[sid] = [[], None, None]
        if kind == "headers":
            state[0].append((HEADERS, event["fields"]))
        elif kind == "data":
            state[0].append((DATA, bytes.fromhex(event["hex"])))
        elif kind == "fin":
            state[1] = "fin"
            state[2] = index
        elif kind == "reset":
            state[1] = "reset"
            state[2] = index

    def blank(sid, status):
        return {"sid": sid, "status": status, "commit_at": None, "origin": None,
                "offset": None, "length": 0, "cache_key": None}

    records = {}
    commits = []
    for sid in sorted(streams):
        frames, terminal, at = streams[sid]
        if terminal == "reset":
            records[sid] = blank(sid, "cancelled")   # contents never matter
        elif terminal is None:
            records[sid] = blank(sid, "incomplete")  # no terminal event seen
        else:
            commits.append((at, sid))

    # Forwarded requests join their pipeline in FIN order, never stream-ID or
    # first-HEADERS order; rejected streams contribute no bytes or offsets.
    commits.sort()
    for _at, sid in commits:
        outcome = finalize(streams[sid][0], routes)
        if outcome is None:
            records[sid] = blank(sid, "rejected")    # atomic: no bytes at all
            continue
        request, cache_key, origin = outcome
        pipeline = pipelines[origin]
        record = blank(sid, "forwarded")
        record["commit_at"] = _at
        record["origin"] = origin
        record["offset"] = len(pipeline)
        record["length"] = len(request)
        record["cache_key"] = cache_key
        records[sid] = record
        pipeline += request

    return {"streams": [records[sid] for sid in sorted(records)],
            "origins": {label: pipeline.hex()
                        for label, pipeline in pipelines.items()}}


def main():
    scenario = json.load(sys.stdin)
    sys.stdout.write(json.dumps(bridge(scenario), ensure_ascii=True))
    sys.stdout.write("\n")
